-- Column-only fixture from read-only production introspection. No customer data.
create table public."contract_audit_trail" ("id" uuid default gen_random_uuid() not null,
"contract_id" uuid not null,
"action" text not null,
"actor_id" uuid,
"actor_role" text,
"actor_name" text,
"actor_email" text,
"ip_address" text,
"user_agent" text,
"geolocation" jsonb,
"details" jsonb default '{}'::jsonb,
"created_at" timestamp with time zone default now());
create table public."contract_parties" ("id" uuid default gen_random_uuid() not null,
"tenant_id" uuid not null,
"contract_id" uuid not null,
"contact_id" uuid,
"company_id" uuid,
"party_snapshot" jsonb not null,
"role" text not null,
"signing_order" integer,
"signature_required" boolean default true not null,
"signature_status" text default 'not_requested'::text not null,
"created_at" timestamp with time zone default now() not null);
create table public."contract_signature_events" ("id" uuid default gen_random_uuid() not null,
"tenant_id" uuid not null,
"contract_id" uuid not null,
"party_id" uuid,
"event_type" text not null,
"signer_email" text,
"signing_order" integer,
"provider" text,
"provider_event_id" text,
"ip_address" inet,
"user_agent" text,
"document_hash" text,
"evidence" jsonb default '{}'::jsonb not null,
"occurred_at" timestamp with time zone default now() not null);
create table public."contract_signing_tokens" ("id" uuid default gen_random_uuid() not null,
"tenant_id" uuid not null,
"contract_id" uuid not null,
"token" text not null,
"signer_email" text not null,
"signer_role" text not null,
"expires_at" timestamp with time zone not null,
"used_at" timestamp with time zone,
"revoked_at" timestamp with time zone,
"created_by" uuid,
"metadata" jsonb default '{}'::jsonb not null,
"created_at" timestamp with time zone default now() not null);
create table public."contracts" ("id" uuid default gen_random_uuid() not null,
"user_id" uuid,
"project_id" uuid,
"title" text not null,
"status" text default 'draft'::text,
"content" jsonb default '{}'::jsonb,
"template_type" text default 'generic'::text,
"signed_at" timestamp with time zone,
"signer_name" text,
"signer_email" text,
"signature_url" text,
"pdf_url" text,
"metadata" jsonb default '{}'::jsonb,
"created_at" timestamp with time zone default now(),
"updated_at" timestamp with time zone default now(),
"tenant_id" uuid,
"client_signature" text,
"client_signed_at" timestamp with time zone,
"admin_signature" text,
"admin_signed_at" timestamp with time zone,
"owner_id" uuid,
"client_id" uuid,
"payment_due_date" timestamp with time zone,
"payment_amount" numeric,
"payment_status" text default 'pending'::text,
"type" text,
"signing_token" text,
"contract_value" numeric default 0,
"cost_basis" numeric default 0,
"margin_amount" numeric default 0,
"deal_id" uuid,
"start_date" timestamp with time zone,
"end_date" timestamp with time zone,
"auto_renew" boolean default false not null,
"renewal_notice_days" integer default 30 not null,
"value" numeric,
"total_value" numeric,
"document_id" uuid,
"contract_number" text,
"description" text,
"owner_user_id" uuid,
"team_id" uuid,
"currency_code" text,
"annual_value" numeric,
"effective_date" date,
"renewal_date" date,
"notice_deadline" date,
"auto_renews" boolean default false not null,
"governing_law" text,
"jurisdiction" text,
"risk_level" text,
"lifecycle_status" text default 'draft'::text not null,
"current_version_id" uuid,
"viewed_at" timestamp with time zone,
"activated_at" timestamp with time zone,
"terminated_at" timestamp with time zone,
"termination_reason" text,
"last_risk_review_at" timestamp with time zone,
"risk_findings" jsonb default '[]'::jsonb not null,
"client_name" text,
"sent_at" timestamp with time zone);
create table public."esignature_consents" ("id" uuid default gen_random_uuid() not null,
"user_id" uuid,
"contract_id" uuid,
"consent_given" boolean default true not null,
"consent_text" text not null,
"consent_method" text not null,
"ip_address" text,
"user_agent" text,
"geolocation" jsonb,
"withdrawn_at" timestamp with time zone,
"created_at" timestamp with time zone default now());
create table public."signature_events" ("id" uuid default gen_random_uuid() not null,
"contract_id" uuid not null,
"signer_id" uuid,
"signer_role" text not null,
"signer_name" text not null,
"signer_email" text not null,
"signer_ip" text,
"event_type" text not null,
"signature_data" text,
"authentication_method" text,
"intent_statement" text,
"device_info" jsonb,
"timestamp" timestamp with time zone default now(),
"content_hash_at_signing" text,
"tamper_seal" text,
"created_at" timestamp with time zone default now());
create table public."tenant_users" ("id" uuid default gen_random_uuid() not null,
"tenant_id" uuid not null,
"user_id" uuid not null,
"role" text default 'member'::character varying not null,
"permissions" jsonb default '[]'::jsonb,
"joined_at" timestamp with time zone default now());
